import ast


@dataclass(slots=True, frozen=True)
class ImportMap:
    """Explicit POSIX import map for static analysis and dependency tracking."""
    imported_modules: set[str]
    import_aliases: dict[str, str]

    @classmethod
    def from_source(cls, source_bytes: bytes) -> "ImportMap":
        tree = ast.parse(source_bytes)
        modules: set[str] = set()
        aliases: dict[str, str] = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    modules.add(alias.name)
                    aliases[alias.name] = alias.asname or alias.name
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    modules.add(node.module)
                    if node.names:
                        aliases[node.names[0].name] = node.names[0].asname or node.module
        return cls(imported_modules=modules, import_aliases=aliases)
